import assert from 'node:assert/strict';

export function assertWorkDiagnostic(stderr, limit) {
  assert(typeof stderr === 'string' && Buffer.byteLength(stderr) <= 512);
  assert(stderr.endsWith('\n'));
  let body = stderr.slice(0, -1);
  assert(!body.includes('\n') && !body.includes('\r'));
  if (body.startsWith('shell: line ')) {
    const rest = body.slice(12);
    const end = rest.indexOf(': ');
    assert(end > 0 && end <= 6);
    const number = rest.slice(0, end);
    assert(number[0] >= '1' && number[0] <= '9');
    for (const digit of number) assert(digit >= '0' && digit <= '9');
    body = rest.slice(end + 2);
  }
  if (body.startsWith('EFBIG: ')) body = body.slice(7);
  if (body.startsWith('tree: ')) body = 'tree ' + body.slice(6);
  assert.equal(body, 'tree work limit exceeded (' + limit + ')');
}

export function assertPhase(entry, report) {
  assert.equal(report.error, undefined);
  assert.deepEqual(report.calls.map(call => [call.method, call.path]), [['lstat', '/root'], ['readdir', '/root']]);
  assert.equal(report.listings.length, 1);
  const listing = report.listings[0];
  const names = entry.entries.filter(item => item.path.startsWith('/root/')).map(item => item.path.slice(6));
  assert.deepEqual(listing, { path: '/root', ...entry.expected.listing, names: names.slice(0, entry.expected.listing.yielded) });
}

